const { createHmac } = require('crypto');
const item = $input.item.json;
const rawHeaders = Array.isArray(item.payload?.headers) ? item.payload.headers : Array.isArray(item.headers) ? item.headers : [];
const parsedHeaders = Object.fromEntries(rawHeaders.map((header) => [String(header.name).toLowerCase(), header.value]));
const objectHeaders = item.headers && !Array.isArray(item.headers) ? item.headers : {};
const headers = { ...parsedHeaders, ...objectHeaders };
const address = (value) => String(value ?? '').match(/<([^>]+)>/)?.[1] ?? String(value ?? '');
const decodeBase64Url = (value) => {
  const normalized = String(value).replace(/-/g, '+').replace(/_/g, '/');
  return Buffer.from(normalized, 'base64').toString('utf8');
};
const textParts = [];
const mimeAttachments = [];
const visitPart = (part) => {
  if (!part || typeof part !== 'object') return;
  if (part.filename) {
    mimeAttachments.push({
      filename: String(part.filename),
      ...(part.mimeType ? { mimeType: String(part.mimeType) } : {}),
      ...(Number.isSafeInteger(Number(part.body?.size)) ? { sizeBytes: Number(part.body.size) } : {}),
    });
  }
  if (part.mimeType === 'text/plain' && part.body?.data) textParts.push(decodeBase64Url(part.body.data));
  for (const child of Array.isArray(part.parts) ? part.parts : []) visitPart(child);
};
visitPart(item.payload);
const fallbackAttachments = Array.isArray(item.attachments) ? item.attachments : [];
const attachmentSource = mimeAttachments.length > 0 ? mimeAttachments : fallbackAttachments;
const payload = {
  gmailMessageId: String(item.id ?? item.messageId),
  gmailThreadId: String(item.threadId),
  fromAddress: address(item.from ?? headers.from).trim().toLowerCase(),
  toAddresses: String(item.to ?? headers.to ?? '').split(',').map(address).map((value) => value.trim().toLowerCase()).filter(Boolean),
  subject: String(item.subject ?? headers.subject ?? ''),
  bodyText: String(item.textPlain ?? item.text ?? (textParts.length > 0 ? textParts.join('\n') : item.snippet) ?? ''),
  receivedAt: new Date(Number(item.internalDate ?? Date.now())).toISOString(),
  attachments: attachmentSource.map((attachment) => ({
    filename: String(attachment.filename ?? attachment.name),
    ...(attachment.mimeType ? { mimeType: String(attachment.mimeType) } : {}),
    ...(Number.isSafeInteger(Number(attachment.sizeBytes ?? attachment.size)) ? { sizeBytes: Number(attachment.sizeBytes ?? attachment.size) } : {}),
  })),
};
const body = JSON.stringify(payload);
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = createHmac('sha256', $env.INGEST_HMAC_SECRET).update(`${timestamp}.${body}`, 'utf8').digest('hex');
return [{ json: { body, timestamp, signature, gmailMessageId: payload.gmailMessageId } }];
